```cpp
#include <algorithm>
#include <cassert>

class MinMaxTracker {
public:
    void add(int v) {
        if (!has_) { lo_ = hi_ = v; has_ = true; }
        else { lo_ = std::min(lo_, v); hi_ = std::max(hi_, v); }
    }
    int min() const { return has_ ? lo_ : 0; }
    int max() const { return has_ ? hi_ : 0; }
    int span() const { return max() - min(); }
    void reset() { has_ = false; lo_ = hi_ = 0; }
private:
    bool has_ = false;
    int lo_ = 0, hi_ = 0;
};

int main() {
    MinMaxTracker t;
    assert(t.span() == 0);
    t.add(512); t.add(40); t.add(900);
    assert(t.min() == 40 && t.max() == 900 && t.span() == 860);
    t.reset();
    assert(t.min() == 0 && t.max() == 0);
}
```
On the Uno you'd call `add(analogRead(pin))` for each sensor while sweeping the bar over the line for a few seconds.

