```cpp
#include <cassert>

int normalize(int raw, int lo, int hi) {
    if (hi <= lo) return 0;
    long v = (static_cast<long>(raw) - lo) * 1000L / (hi - lo);
    if (v < 0) return 0;
    if (v > 1000) return 1000;
    return static_cast<int>(v);
}

int main() {
    assert(normalize(470, 40, 900) == 500);
    assert(normalize(1000, 40, 900) == 1000);
}
```
(470 − 40) × 1000 / 860 = 430000 / 860 = 500 exactly.

