```cpp-snippet
// src/LineCal.h
#pragma once
class MinMaxTracker {
public:
    void add(int v);
    int min() const;
    int max() const;
    int span() const;
    void reset();
private:
    bool has_ = false;
    int lo_ = 0, hi_ = 0;
};
int normalize(int raw, int lo, int hi);
```

```cpp-snippet
// src/LineCal.cpp
#include "LineCal.h"
void MinMaxTracker::add(int v) {
    if (!has_) { lo_ = hi_ = v; has_ = true; return; }
    if (v < lo_) lo_ = v;
    if (v > hi_) hi_ = v;
}
int MinMaxTracker::min() const { return has_ ? lo_ : 0; }
int MinMaxTracker::max() const { return has_ ? hi_ : 0; }
int MinMaxTracker::span() const { return max() - min(); }
void MinMaxTracker::reset() { has_ = false; lo_ = hi_ = 0; }
int normalize(int raw, int lo, int hi) {
    if (hi <= lo) return 0;
    long v = ((long)raw - lo) * 1000L / (hi - lo);
    return v < 0 ? 0 : (v > 1000 ? 1000 : (int)v);
}
```

Note the library avoids `std::min` because the AVR toolchain has no standard library headers; plain comparisons work everywhere.

```arduino
#include <LineCal.h>
MinMaxTracker cal;
void setup() {
  Serial.begin(115200);
  unsigned long start = millis();
  while (millis() - start < 5000) cal.add(analogRead(A0));
  Serial.print("min "); Serial.print(cal.min());
  Serial.print(" max "); Serial.println(cal.max());
}
void loop() {
  Serial.println(normalize(analogRead(A0), cal.min(), cal.max()));
  delay(50);
}
```

`library.properties`: `name=LineCal`, `version=0.1.0`, `author=...`, `maintainer=...`, `sentence=Calibrate and normalize reflectance sensors.`, `paragraph=...`, `category=Sensors`, `url=...`, `architectures=*`.

```python
from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val, self.left, self.right = val, left, right


def build_tree(values):
    """Build a tree from a level-order list where None marks a missing child."""
    if not values or values[0] is None:
        return None
    root = TreeNode(values[0])
    queue, i = deque([root]), 1
    while queue and i < len(values):
        node = queue.popleft()
        for side in ("left", "right"):
            if i < len(values) and values[i] is not None:
                child = TreeNode(values[i])
                setattr(node, side, child)
                queue.append(child)
            i += 1
    return root


def tree_to_list(root):
    """Level-order list with None for gaps, trailing Nones removed."""
    out, queue = [], deque([root])
    while queue:
        node = queue.popleft()
        if node is None:
            out.append(None)
            continue
        out.append(node.val)
        queue.append(node.left)
        queue.append(node.right)
    while out and out[-1] is None:
        out.pop()
    return out


def inorder_iterative(root):
    out, stack, node = [], [], root
    while node or stack:
        while node:
            stack.append(node)
            node = node.left
        node = stack.pop()
        out.append(node.val)
        node = node.right
    return out


assert inorder_iterative(build_tree([4, 2, 6, 1, 3, 5, 7])) == [1, 2, 3, 4, 5, 6, 7]
```

