import numpy as np


def sample_stats(x):
    x = np.asarray(x, dtype=float)
    return float(x.mean()), float(x.var())


def mean_tolerance(sigma, n, k=4):
    return k * sigma / np.sqrt(n)


rng = np.random.default_rng(1)
