```python
def line_position(values, last=2000, floor=100):
    num = den = 0
    for i, v in enumerate(values):
        if v >= floor:
            num += i * 1000 * v
            den += v
    if den == 0:
        return 0 if last < 2000 else 4000
    return num // den


assert line_position([0, 0, 500, 500, 0]) == 2500
```

Arduino port:

```cpp-snippet
int linePosition(const int v[5], int last) {
  long num = 0, den = 0;
  for (int i = 0; i < 5; i++) {
    if (v[i] >= 100) { num += (long)i * 1000L * v[i]; den += v[i]; }
  }
  if (den == 0) return last < 2000 ? 0 : 4000;
  return (int)(num / den);
}
```

