```python
import math
import numpy as np


def normal_cdf(x, mu, sigma):
    return 0.5 * (1 + math.erf((x - mu) / (sigma * math.sqrt(2))))


def misclass_rate(t, mu_w, s_w, mu_b, s_b):
    return 0.5 * ((1 - normal_cdf(t, mu_w, s_w)) + normal_cdf(t, mu_b, s_b))


def best_threshold(mu_w, s_w, mu_b, s_b, steps=10_000):
    ts = np.linspace(mu_w, mu_b, steps)
    rates = [misclass_rate(t, mu_w, s_w, mu_b, s_b) for t in ts]
    return float(ts[int(np.argmin(rates))])


t = best_threshold(120, 15, 300, 40)
print(round(t, 1), misclass_rate(t, 120, 15, 300, 40))
```

The exact optimum differs slightly from the equal-z rule of thumb (≈169) because the densities have different heights, but the lesson holds: lean toward the narrower distribution.

