#include <algorithm>
#include <cassert>
#include <cmath>

class Pid {
public:
    Pid(double kp, double ki, double kd) : kp_(kp), ki_(ki), kd_(kd) {}
    void setLimits(double lo, double hi) { lo_ = lo; hi_ = hi; }
    double update(double error, double dt) {
        integral_ += error * dt;
        if (ki_ > 0) integral_ = std::clamp(integral_, lo_ / ki_, hi_ / ki_);
        double deriv = first_ ? 0.0 : (error - prev_) / dt;
        first_ = false;
        prev_ = error;
        double out = kp_ * error + ki_ * integral_ + kd_ * deriv;
        return std::clamp(out, lo_, hi_);
    }
    void reset() { integral_ = 0; prev_ = 0; first_ = true; }
private:
    double kp_, ki_, kd_;
    double lo_ = -1e9, hi_ = 1e9;
    double integral_ = 0, prev_ = 0;
    bool first_ = true;
};

int main() {
    Pid p(2, 0, 0);
    assert(p.update(1.5, 0.1) == 3.0);
}
```

Without the clamp, 100 updates of error 1.0 build an integral of 10; when the error flips sign it takes many steps to "unwind" before the output leaves the limit. That lag is integral windup, and you'll see it on the motor this week.

