#include <algorithm>
#include <cassert>
#include <cmath>
#include <iostream>

class Pid {
public:
    Pid(double kp, double ki, double kd) : kp_(kp), ki_(ki), kd_(kd) {}
    void setLimits(double lo, double hi) { lo_ = lo; hi_ = hi; }
    double update(double error, double dt) {
        integral_ += error * dt;
        if (ki_ > 0) integral_ = std::clamp(integral_, lo_ / ki_, hi_ / ki_);
        double deriv = first_ ? 0.0 : (error - prev_) / dt;
        first_ = false;
        prev_ = error;
        return std::clamp(kp_ * error + ki_ * integral_ + kd_ * deriv, lo_, hi_);
    }
    void reset() { integral_ = 0; prev_ = 0; first_ = true; }
private:
    double kp_, ki_, kd_;
    double lo_ = -1e9, hi_ = 1e9;
    double integral_ = 0, prev_ = 0;
    bool first_ = true;
};

double simulateFirstOrder(Pid& pid, double setpoint, double tau, int steps, double dt) {
    double y = 0;
    for (int i = 0; i < steps; ++i) {
        double u = pid.update(setpoint - y, dt);
        y += dt * (u - y) / tau;
    }
    return y;
}

int main() {
    Pid p(2, 0, 0), pi(2, 20, 0);
    double a = simulateFirstOrder(p, 100, 0.1, 2000, 0.001);
    double b = simulateFirstOrder(pi, 100, 0.1, 2000, 0.001);
    std::cout << "P only: " << a << "  PI: " << b << "\n";
    assert(std::fabs(a - 200.0 / 3) < 0.5);
    assert(std::fabs(b - 100) < 0.5);
}
```

The P-only result is the **steady-state error** you'll measure on the real motor on Tuesday: a proportional controller needs a nonzero error to produce any output at all. The integral term accumulates that leftover error until it's gone.

