import math
import os
import tempfile

import pandas as pd


def rms(errors):
    return math.sqrt(sum(e * e for e in errors) / len(errors))


def crossings_per_second(errors, dt):
    count, last_sign = 0, 0
    for e in errors:
        s = (e > 0) - (e < 0)
        if s == 0:
            continue
        if last_sign and s != last_sign:
            count += 1
        last_sign = s
    return count / (len(errors) * dt)


def summarize_csv(path, dt=0.02):
    errs = pd.read_csv(path)["error"].tolist()
    return {"rms": rms(errs), "crossings_per_s": crossings_per_second(errs, dt), "samples": len(errs)}


sig = [round(500 * math.sin(2 * math.pi * 2 * i * 0.02 + 0.3)) for i in range(200)]
with tempfile.TemporaryDirectory() as d:
    p = os.path.join(d, "run.csv")
    pd.DataFrame({"i": range(200), "error": sig}).to_csv(p, index=False)
    print(summarize_csv(p))
```

